import sys

def maxGoods(budget, coupons):
    threshold = {}
    for i in range(len(coupons)):
        if coupons[i][1] != budget:
            threshold[i+1] = min(coupons[i][1]-coupons[i][0], budget+coupons[i][1]-budget)
        else:
            threshold[i+1] = budget-coupons[i][0]
    return sum(min(threshold[i], b) - coupon_price for i, (coupon_price, discount,**) in enumerate(coupons))

