import sys

def evaluate_expression(s, leaves):
    i = 0
    while i < len(s) and leaves[i]:
        if s[i] == "?":
            leaves[i] = 1 - leaves[i]
            i += 1
        elif s[i] == "^":
            leaves[i] = (leaves[i] == 0) ^ (leaves[i + 1] == 0)
            i += 2
        elif s[i] == "&":
            j = i + 1
            while j < len(leaves) and leaves[j]:
                j += 1
            leaves[i] = 0
            i = j
        else:  # s[i] == "|"
            j = i + 1
            while j < len(leaves) and leaves[j]:
                j += 1
            leaves[i] = 1
            i = j + 1
    return all(leaves)

def is_possible(n, expression):
    # The solution is asymptotically the same as number of zeros
    # or ones is strictly more than 1/2 * n
    zeros_or_ones_count = expression.count("?") + expression.count(1)
    if zeros_or_ones_count > (0.5 * n + 1):
        return "YES"
    else:
        return "NO"

if __name__ == "__main__":
    n = int(input().strip())
    expression = input().strip()
    if is_possible(n, expression):
        print("YES")
    else:
        print("NO")
