from itertools import combinations

def find_red_wires(points):
    x_coords = set()
    y_coords = set()
    for a, b in points:
        x_coords.add(a)
        y_coords.add(b)
    red_wires = []
    for x in sorted(x_coords):
        for y in y_coords:
            if x + y in points:
                red_wires.append((x, y, x, y))
    return red_wires

def find_blue_wires(points):
    y_coords = set()
    for a, b in points:
        y_coords.add(a)
    blue_wires = []
    for y in sorted(y_coords * 2):
        for x in range(2):
            if y + x in points:
                blue_wires.append((x, y, x, y))
    return blue_wires

def print_scheme(red_wires, blue_wires):
    print(len(red_wires), len(blue_wires))
    for wire in red_wires + blue_wires:
        print(*wire)

