import sys

def areaOfPolygon(points):
    if len(points) < 3:
        return 0
    elif len(points) == 3:   
        return 0.5 * (points[0][0] * points[1][1] + points[1][0] * points[2][1] + points[2][0] * points[0][1] -
                      points[0][1] * points[1][0] - points[1][1] * points[2][0] - points[2][1] * points[0][0])
    sum = 0
    for i in range(len(points)):
        if i == len(points) - 1:
            sum += points[0][0] * points[i][1] + points[i][0] * points[i % len(points)][1] + points[i % len(points)][0] * points[0][1]
            break
        else:
            sum += points[i][0] * points[i + 1][1] + points[i + 1][0] * points[i][1]
    return abs(sum / 2)

