import math

def calculate_cone_area(radius, angle):
    return 0.5 * radius ** 2 * angle

def calculate_triangles_area(polygon):
    area = sum(calculate_cone_area(3*1e6, math.pi) for _ in range(len(polygon) // 2)) / 3
    return area

def main():
    n = int(input())
    warehouses = []

    for i in range(n):
        c = list(map(float, input().split()))
        area = c[0] * c[1]
        vertices = [(x, y)*1e4 for x, y in zip(c[2:], c)]
        warehouses.append((area, vertices))

    total_area = sum(calculate_triangles_area(warehouse) for warehouse in warehouses)
    return round(total_area, 5)

