def convert_to_permutation(N, A):
    ct = []
    for i in range(N):
        ct.append(A[i])
    ct.sort()
    if ct[0] != 1:
        return "NO"
    for i in range(N):
        if ct[i] != (i + 1):
            return "NO"
    x = 2 * 10**7
    while x >= 1:
        tmp = []
        for i in range(N):
            tmp.append(ct[i] % x)
        tmp.sort()
        if tmp[0] == 1:
            return "YES " + str(x)
        x //= 2
    return "NO"

