        input_str = input().strip()
        print(count_palindrome_positions_helper(input_str))

def is_palindrome(input_str):
    return input_str == input_str[::-1]

def count_palindrome_positions_helper(input_str):
    count = 0
    len_str = len(input_str)
    for i in range(len_str):
        if is_palindrome(input_str[:i] + input_str[i:]):
            count += 1
    return count

