from itertools import product

def nutritional_formula(formula, leaf_values):
    stack = []

    for char in formula:
        if char == '(':
            stack.append(char)
        elif char == ')' and stack and stack[-1] == '(':
            stack.pop()
        else:
            stack.append(char)

    leaves = {i + 1 for i, value in enumerate(leaf_values) if value == '?'}
    results = []
    for sample in product(*([1],) * len(leaves)):
        formula_copy = []
        i = 0
        while i < len(formula):
            char = formula[i]
            if char == '(':
                i += 1
                stack = []
                while stack and stack[-1] == '(':
                    formula_copy.append(formula[i])
                    i += 1
                stack.append('-')
            elif char == ')' and stack and stack[-1] == '-':
                stack.pop()
            elif char == '?':
                formula_copy.append(str(sample[leaves.index(i + 1)]))
            else:
                formula_copy.append(char)
            i += 1

        while stack:
            formula_copy.append(stack.pop())

        parsed_formula = ''.join(formula_copy)

        if eval(parsed_formula):
            results.append(1)
        else:
            results.append(0)

    return [0 if rv == 1 else 1 for rv in results]

def can_determine_species(n, formula):
    leaf_values = list(range(4))
    result = nutritional_formula(formula, leaf_values)
    return all(rv == 1 for rv in result)

# Example usage:
n = int(input().strip())
formula = input().strip()

if can_determine_species(n, formula):
    print("YES")
else:
    print("NO")
