import heapq

def solve(n, m, queries):
    nums = [0] * n
    positions = [[] for _ in range(n)]
    islands = []
    result = [0] * m
    taken = set()

    for q in queries:
        t, pos, height = q
        if t == 1:
            heapq.heappush(positions[pos], height)
            heapq.heappush(positions[pos], -height)
            taken.add(height)
            nums[pos] = 1
        elif t == 2:
            is_landfall = False
            for i in range(n):
                if nums[i] and not nums[i] in taken:
                    result[pos-1] = len(positions[i])
                    is_landfall = True
                    break
            if not is_landfall:
                result[pos-1] = 2
            else:
                for i in range(n):
                    if nums[i] == nums[positions[i][0]]:
                        nums[i] = 0
                        heapq.heappop(positions[i])
                                heapq.heappush(positions[i], -nums[positions[i][0]])
                        nums[positions[i][0]] = 0
                        heapq.heappop(positions[i])
                        for j in range(len(positions[i])):
                            if positions[i][j] != positions[positions[i][0]][j]:
                                num_pos = positions[i][j] if positions[i][j] < positions[positions[i][0]][j] else positions[positions[i][0]][j]
                                taken.add(positions[i][num_pos][0])
        elif t == -1:
            nums[pos] = 0
            for i in range(len(positions[pos])):
                if nums[positions[pos][i][0]]:
                    heapq.heappush(positions[pos], -nums[positions[pos][i][0]])
            for i, p in enumerate(positions[pos]):
                if not nums[p[0]]:
                    heapq.heappush(positions[pos], -nums[p[0]])
            if not nums[pos]:
                if positions[pos]:
                    left_max = (-heapq.heappop(positions[pos])) ** 2
                    right_max = sum(x ** 2 for x in positions[pos][::-1]) ** 0.5
                    result[pos-1] = left_max + right_max

        elif t == -2:
            for i in range(len(positions[pos])):
                if nums[positions[pos][i][0]] and nums[positions[pos][i][0]] != pos:
                    nums[positions[pos][i][0]] = 0
                    heapq.heappop(positions[pos])
            for i, p in enumerate(positions[pos]):
                if not nums[p[0]]:
                    heapq.heappush(positions[pos], -nums[p[0]])

    return result

# Read input
