    x = [coord[0] for coord in points]
    y = [coord[1] for coord in points]
    return 0.5 * abs(sum(x[i] * y[i + 1] - x[i + 1] * y[i] for i in range(len(x) - 1)))

def main():
    n = int(input())
    points = list(read_points())

    areas = set()
    for points_group in itertools.combinations(points, n):
        area = calculate_area(list(points_group))
        areas.add(math.floor(area))

    return sum(areas) / len(areas)

