import sys

def evaluate_formula(formula):
    stack = []
    for token in formula:
        if token in '01':
            stack.append(str(int(token)))
        elif token in '()|&^':
            if token == '(':
                top = stack.pop()
                while len(top) > 1:
                    tokens = top.pop()
                    if '=' in tokens:
                        key, value = tokens.split('=')
                        stack.append(key)
                        for diff in range(int(value)):
                            if top.pop() == '0':
                                break
                            else:
                                top.pop()
                    elif '!' in tokens:
                        top.pop()
                    else:
                        tokens = ''
            elif token == '|':
                for tokens in stack.pop():
                    for next in stack.pop():
                        stack.append(tokens + next)
            elif token == '&':
                for tokens in stack.pop():
                    for next in reversed(stack.pop()):
                        if next == '0':
                            break
                        else:
                            stack.append(tokens + next)
            elif token == '^':
                for tokens in stack.pop():
                    for next in reversed(stack.pop()):
                        if next == '0':
                            stack.append(tokens)
                            break
                        elif tokens == '0' and next == '0':
                            stack.append('1')
                            break
                        elif tokens == '1' and next == '1':
                            stack.append('1')
                            break
                        else:
                            stack.append('0')
                            break
    return "".join(stack)

