from itertools import combinations

MOD = 998244353

def f(subsequence, s, dp):
    if not subsequence:
        return 0
    if len(subsequence) == 1:
        return dp[subsequence[0]] if dp else s[ord(subsequence[0]) - ord("a")]
    for char in s:
        for i in range(len(subsequence)):
            new_subsequence = list(subsequence)
            new_subsequence[i] = char
            dp[subsequence] = (dp.get(subsequence, 0) + dp.get(tuple(new_subsequence), 0)) % MOD
    return dp.get(tuple(subsequence), 0)

def calculate_F(n, strings):
    result, s = {}, [ord(c) for c in "abcdefghijklmnopqrstuvwxyz"]
    for subsequence in combinations(range(n), n//2):
        formed = set()
        for i in range(1, n//2 + 1):
            part1 = tuple(sorted(strings[:n//2][:-i] + [t for k in subsequence for t in strings[n//2+k:n][0:i]]))
            part2 = sorted(strings[i:n//2][::-1] + [t for k in subsequence for t in strings[2*i:n][0:i]])
            if (part1 ^ part2) in formed:
                return -1
            if part1 not in formed:
                formed.add(part1)
            if part2 not in formed:
                formed.add(part2)
        dp = {tuple(k): value and 1 or 0 for k, value in formed.items()}
        result[tuple(subsequence)] = sum(f(subsequence, s, dp) * len(subsequence), 0) % MOD
    return result

