def find_shortest_sequence(d, n, password_list):
    k = 0
    while d:
        if d % 2 == 0:
            k += 1
        d >>= 1
    if d != 1:
        sys.exit('Invalid value of d')

    button_presses = set()
    for password in password_list:
        index = 0
        for bit in password:
            if bit == '1':
                button_presses.add(index)
            index += 1
        index = 0
        for digit in reversed(password):
            if digit == '0':
                button_presses.add(index)
            index += 1

    min_presses = sys.maxsize
    for seq_len in range(k, d + 1):
        bits = [0] * (2 ** d)
        for i in range(seq_len):
            bit = i % d
            if bit in button_presses:
                bits[bit] = 1
            else:
                bits[bit] = 0

        if bits == [0] * d:
            min_presses = seq_len
            break

    if min_presses == sys.maxsize:
        print('Not possible')
    else:
        print(input)
        print(min_presses)
