        b_ind = sum([len(i) for i in b_lines[:-1]])        # this would be the highest x.

        h_line = b_line = None
        for hi, (h_x1, h_y1, h_x2, h_y2) in enumerate(h_lines):
            if h_y1 <= h_ind and h_y2 >= h_ind:
                h_line = f"hotbar {hi+1} {sqrt((h_x2+h_x1)/2)} {sqrt((h_x2+h_x1)/2) + 1.e-6} {h_yy}"
        for bl, (b_x1, b_y1, b_x2, b_y2) in enumerate(b_lines):
            if b_x1 <= b_ind and b_x2 >= b_ind:
                b_line = f"brttop {bl+1} {sqrt((b_x2+b_x1)/2)} {sqrt((b_x2+b_x1)/2) + 1.e-6} {b_yy}"

        print(f"Size: {p_per_b * ("hotbar" if len(h_lines) else "brttop") + 1} {h_line} {b_line}\n")

        h_lines = [h_lines[0]]
        b_lines = [b_lines[0]]

        for _ in range(1, len(h_lines)):
            h_lines.remove(h_lines[0])
            if h_lines[-1].x1 <= h_lines[-1].x2:
                h_lines.append(h_lines[-1])
        for _ in range(1, len(b_lines)):
            b_lines.remove(b_lines[0])
            if b_lines[-1].y1 <= b_lines[-1].y2:
                b_lines.append(b_lines[-1])

        h_points = [i[:-4] for i in h_lines]
        b_points = [i[:-4] for i in b_lines]

        p_per_b = (len(b_points) + len(h_points) - 1) // len(h_points)
