```\#include <bits/stdc++.h>

using namespace std;

const int MOD = 998244353;

long long power(long long base, long long exp) {
    long long ans = 1;
    while (exp) {
        if (exp & 1) {
            ans = (ans * base) % MOD;
        }
        base = (base * base) % MOD;
        exp >>= 1;
    }
    return ans;
}

int n;

long long fact[100000], inv[100000];

long long comb(int n, int m) {
    return (inv[m] * inv[n-m]) % MOD;
}

long long f(string s) {
    if (s.size() == 1) {
        return (power(2, s[0] - 'a') + power(2, s[0] - 'a')) % MOD;
    }

    if (n == 1) {
        return (power(2, s[0] - 'a') * 2 + power(2, s[0] - 'a') * 2 + 2) % MOD;
    }

    if (s.size() - s.size() % n == 0) {
        if (n == 3 or n == 5) {
            return power(2, s.size() % 2) % MOD;
        } else {
            return power(2, s.size() % n * 2 + s.size() % n / 2 * n - 1) % MOD;
        }
    }

    int ind = 0;
    for (int i = 0; i < (int)s.size() - s.size() % n; i++) {
        if (ind == n - 1 and i == n - 1) break;
        if (s[i] - 'a' == s[n - 1] - 'a') ind++;
    }

    long long ans = 1;
    if (ind == n) ans = 1;

    for (int i = 0; i < n; i++) {
        if (i < ind) ans = (ans * (i + 1)) % MOD;
        if (i >= ind) ans = (ans * (n - ind + i)) % MOD;
        ans = (ans + (s[ind] - 'a') * comb(s.size() + n - i - 1, n - i)) % MOD;
    }

    return power(2, s.size() % n) * ans % MOD;
}

int main() {
    cin >> n;
    string s;
    getline(cin, s);

    fact[0] = 1;
    inv[0] = 1;

    for (int i = 1; i < 100000; i++) {
        fact[i] = (fact[i-1] * i) % MOD;
        inv[i] = power(fact[i], MOD - 2);
    }

    string str;
    getline(cin, str);
    s += str;

    string temp, ans;

    map<string, int> freq;
    while (n--) {
        getline(cin, temp);
        string ans = s;
        int len = s.size();
        for (int i = 0; i < 26; i++) {
            string suf = s;
            for (char c = 'a'; c <= 'z'; c++) {
                if (c != temp.back()) suf += c;
            }
            sort(suf.begin(), suf.end());
            suf.erase(unique(suf.begin(), suf.end()), suf.end());

            if (suf  != temp) {
                s = temp;
            }
        }

        for (auto it = freq.lower_bound(s); it != freq.end(); it++) {
            ans += it->first[0];
        }

        for (auto it = freq.begin(); it != freq.end(); it++) {
            ans += it->first[0];
            frequency += comb(it->first.size() - 1, count(freq.begin(), freq.end(), it->first));
        }
        ans += 'a';
    }

    cout << ans;
    return 0;
}




